-- ======================================================================
-- V3: 申込者アカウント（ログイン）、申込取消ステータスと遷移
--  - M_APPLICANT にパスワードハッシュ・アカウント発行日時・パスワード変更日時を追加（ログイン ID は申込者番号）
--  - M_STATUS に 90101 申込取消 を追加（大分類 9：取消）
--  - M_STATUS_TRANSITION に操作コード 15（取消）の遷移 56〜74 を追加
-- ======================================================================
ALTER TABLE M_APPLICANT ADD PASSWORD_HASH NVARCHAR(100) NULL;
ALTER TABLE M_APPLICANT ADD ACCOUNT_ISSUED_AT DATETIME2(3) NULL;
ALTER TABLE M_APPLICANT ADD PASSWORD_CHANGED_AT DATETIME2(3) NULL;


